import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.mRCPFc5l.js";const s="/screenshots/de/erste-schritte/oberflaeche/space-navigation.png",a="/screenshots/de/erste-schritte/oberflaeche/grid-bereich.png",l="/screenshots/de/erste-schritte/oberflaeche/grid-werkzeugleiste.png",m=JSON.parse('{"title":"Die Oberfläche im Überblick","description":"Aufbau der ApptiveGrid-Oberfläche — Seitenleiste, Space-Bereiche, Ansichtswechsel und Einstellungen.","frontmatter":{"title":"Die Oberfläche im Überblick","description":"Aufbau der ApptiveGrid-Oberfläche — Seitenleiste, Space-Bereiche, Ansichtswechsel und Einstellungen."},"headers":[],"relativePath":"erste-schritte/oberflaeche.md","filePath":"erste-schritte/oberflaeche.md","lastUpdated":1786260457000}'),d={name:"erste-schritte/oberflaeche.md"};function o(h,e,c,g,u,p){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="die-oberflache-im-uberblick" tabindex="-1">Die Oberfläche im Überblick <a class="header-anchor" href="#die-oberflache-im-uberblick" aria-label="Permalink to &quot;Die Oberfläche im Überblick&quot;">​</a></h1><p>ApptiveGrid ist durchgehend zweigeteilt: links eine <strong>Seitenleiste</strong> zur Navigation, rechts der <strong>Inhaltsbereich</strong>. Was in der Seitenleiste steht, hängt davon ab, wo Sie sich befinden.</p><h2 id="die-space-ubersicht" tabindex="-1">Die Space-Übersicht <a class="header-anchor" href="#die-space-ubersicht" aria-label="Permalink to &quot;Die Space-Übersicht&quot;">​</a></h2><p>Nach der Anmeldung landen Sie auf der Übersicht aller Spaces.</p><p>Sie finden hier:</p><table tabindex="0"><thead><tr><th>Element</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Alle Spaces</strong></td><td>Alle Spaces, auf die Sie Zugriff haben</td></tr><tr><td><strong>Mit mir geteilt</strong></td><td>Nur Spaces, die andere für Sie freigegeben haben</td></tr><tr><td><strong>Neuen Space erstellen</strong></td><td>Legt einen leeren Space an</td></tr><tr><td><strong>Space suchen</strong></td><td>Filtert die Liste nach Namen</td></tr><tr><td><strong>Nach Kategorie gruppieren</strong></td><td>Bündelt Spaces nach einer zugewiesenen Kategorie</td></tr></tbody></table><p>Darunter erscheinen Vorlagen unter der Überschrift <em>Oder starten Sie mit einer Vorlage</em>.</p><p>Haben Sie noch keinen Space, sehen Sie stattdessen den Hinweis <em>Erstellen Sie Ihren ersten Space</em>.</p><h2 id="innerhalb-eines-space" tabindex="-1">Innerhalb eines Space <a class="header-anchor" href="#innerhalb-eines-space" aria-label="Permalink to &quot;Innerhalb eines Space&quot;">​</a></h2><p>Öffnen Sie einen Space, wechselt die Seitenleiste in die Space-Navigation. Sie gliedert sich in drei Bereiche:</p><p><img src="'+s+'" alt="Die Seitenleiste innerhalb eines Space mit den Bereichen Grids, Seiten und Flows"></p><h3 id="grids" tabindex="-1">Grids <a class="header-anchor" href="#grids" aria-label="Permalink to &quot;Grids&quot;">​</a></h3><p>Ihre Datentabellen. Unter jedem Grid stehen zwei Gruppen:</p><ul><li><strong>Ansichten</strong> — alle Darstellungen dieses Grids</li><li><strong>Formulare</strong> — alle Eingabemasken dieses Grids</li></ul><p>Über <em>Erstellen</em> legen Sie eine neue Ansicht oder ein neues Formular an.</p><div class="tip custom-block"><p class="custom-block-title">Lange Grid-Listen</p><p>Standardmäßig zeigt die Navigation die ersten <strong>10</strong> Grids; der Rest ist hinter <em>Mehr anzeigen</em> eingeklappt. Diese Zahl können Sie in den <a href="/spaces/navigation">Space-Einstellungen</a> ändern.</p></div><h3 id="seiten" tabindex="-1">Seiten <a class="header-anchor" href="#seiten" aria-label="Permalink to &quot;Seiten&quot;">​</a></h3><p>Alle Seiten des Space, die Sie als Portal oder interne Dokumentation verwenden.</p><h3 id="flows" tabindex="-1">Flows <a class="header-anchor" href="#flows" aria-label="Permalink to &quot;Flows&quot;">​</a></h3><p>Alle Automatisierungen des Space.</p><div class="tip custom-block"><p class="custom-block-title">Reihenfolge anpassen</p><p>Ob <strong>Grids vor Seiten</strong> oder <strong>Seiten vor Grids</strong> stehen, legen Sie in den Space-Einstellungen fest. Wenn Ihr Team hauptsächlich mit Portalen arbeitet, ist <em>Seiten vor Grids</em> meist praktischer.</p></div><h2 id="der-grid-bereich" tabindex="-1">Der Grid-Bereich <a class="header-anchor" href="#der-grid-bereich" aria-label="Permalink to &quot;Der Grid-Bereich&quot;">​</a></h2><p>Öffnen Sie ein Grid, sehen Sie immer eine bestimmte <strong>Ansicht</strong> davon — nie das Grid selbst. Über die Seitenleiste wechseln Sie zwischen den Ansichten.</p><p><img src="'+a+'" alt="Der Grid-Bereich mit Seitenleiste, Werkzeugleiste und Tabelle"></p><p>Die Werkzeugleiste über der Tabelle enthält:</p><p><img src="'+l+'" alt="Die Werkzeugleiste über der Tabelle"></p><table tabindex="0"><thead><tr><th>Werkzeug</th><th>Zweck</th></tr></thead><tbody><tr><td><strong>Filter</strong></td><td>Legt fest, welche Einträge sichtbar sind</td></tr><tr><td><strong>Sortieren</strong></td><td>Legt die Reihenfolge fest</td></tr><tr><td><strong>Gruppieren</strong></td><td>Bündelt Einträge nach einem Feld</td></tr><tr><td><strong>Ausgeblendet</strong></td><td>Blendet Spalten aus und wieder ein</td></tr><tr><td><strong>Suchen</strong></td><td>Durchsucht Einträge</td></tr><tr><td><strong>Teilen</strong></td><td>Erzeugt einen Link oder QR-Code auf die Ansicht</td></tr><tr><td><strong>Weitere</strong> (⋮)</td><td>CSV-Export, Duplizieren, Spalten umsortieren, Leerzustand bearbeiten</td></tr></tbody></table><p>Ein Klick auf eine Zeile öffnet den Eintrag in der Detailansicht.</p><div class="warning custom-block"><p class="custom-block-title">Wenn eine Schaltfläche fehlt</p><p>ApptiveGrid blendet Funktionen aus, für die Ihnen die Berechtigung fehlt — es erscheint keine Fehlermeldung. Sehen Sie eine erwartete Schaltfläche nicht, prüfen Sie Ihre Rolle im Space. Siehe <a href="/fehlerbehebung/fehlende-schaltflaechen">Ich sehe eine Schaltfläche nicht</a>.</p></div><h2 id="der-formular-bereich" tabindex="-1">Der Formular-Bereich <a class="header-anchor" href="#der-formular-bereich" aria-label="Permalink to &quot;Der Formular-Bereich&quot;">​</a></h2><p>Der Formular-Editor hat drei Reiter:</p><ul><li><strong>Seiten</strong> — Felder und Textblöcke anordnen, Formularseiten verwalten</li><li><strong>Layout</strong> — Farben, Logo, Hintergrundbild, Style der Felder</li><li><strong>Mehr</strong> — Speichern um später fortzufahren, automatisches Absenden, mehrere Sprachen</li></ul><p>Links stehen die noch nicht verwendeten Felder unter <em>Verfügbare Felder</em>. Rechts entsteht die Vorschau des Formulars.</p><h2 id="der-seiten-bereich" tabindex="-1">Der Seiten-Bereich <a class="header-anchor" href="#der-seiten-bereich" aria-label="Permalink to &quot;Der Seiten-Bereich&quot;">​</a></h2><p>Der Seiteneditor arbeitet wie ein Textdokument: Sie tippen los, und mit der <strong>Leertaste</strong> öffnet sich die Blockauswahl. Der Platzhaltertext lautet <em>Beginnen Sie zu tippen oder drücken Sie die Leertaste, um die Blockauswahl zu öffnen</em>.</p><p>Über <em>Strukturmodus anzeigen</em> blenden Sie zwei zusätzliche Panels ein:</p><ul><li><strong>Seitenstruktur</strong> — der Blockbaum, zum Umsortieren und für verschachtelte Layouts</li><li><strong>Blockeinstellungen</strong> — die Einstellungen des ausgewählten Blocks</li></ul><p>Eine Seite hat zwei Modi: <strong>Editor</strong> zum Bearbeiten und <strong>Anwendung</strong> für die Vorschau, wie Besucher sie sehen.</p><h2 id="der-flow-bereich" tabindex="-1">Der Flow-Bereich <a class="header-anchor" href="#der-flow-bereich" aria-label="Permalink to &quot;Der Flow-Bereich&quot;">​</a></h2><p>Der Flow-Editor ist eine Arbeitsfläche mit Knoten und Verbindungen.</p><ul><li>Links wählen Sie neue Schritte aus, aufgeteilt in <strong>Trigger</strong>, <strong>Aktionen</strong> und <strong>Helfer</strong>.</li><li>Ein Klick auf einen Schritt öffnet dessen Einstellungen.</li><li>Die Werkzeuge <em>Auf alle Knoten zentrieren</em>, <em>Knoten automatisch anordnen</em> und <em>Minimap umschalten</em> helfen bei großen Flows.</li></ul><p>Über den Reiter <strong>Verlauf</strong> sehen Sie vergangene Durchläufe mit Startzeit, Dauer, Anzahl der Schritte und Status.</p><h2 id="einstellungen" tabindex="-1">Einstellungen <a class="header-anchor" href="#einstellungen" aria-label="Permalink to &quot;Einstellungen&quot;">​</a></h2><p>Es gibt zwei getrennte Einstellungsbereiche — eine häufige Verwechslung:</p><h3 id="konto-einstellungen" tabindex="-1">Konto-Einstellungen <a class="header-anchor" href="#konto-einstellungen" aria-label="Permalink to &quot;Konto-Einstellungen&quot;">​</a></h3><p>Gelten für <strong>Sie persönlich</strong>, über <em>Profil &amp; Einstellungen</em>:</p><ul><li><strong>Profil</strong> — Name, Profilbild, Konto löschen</li><li><strong>Zahlung</strong> — Tarif und Abrechnung</li><li><strong>API-Zugangsdaten</strong> — Schlüssel für den Zugriff über die Programmierschnittstelle</li></ul><h3 id="space-einstellungen" tabindex="-1">Space-Einstellungen <a class="header-anchor" href="#space-einstellungen" aria-label="Permalink to &quot;Space-Einstellungen&quot;">​</a></h3><p>Gelten für <strong>einen Space</strong>:</p><ul><li><strong>Allgemein</strong> — Tarif, Sitzplätze, Space-Kennung, Navigationsreihenfolge</li><li><strong>Webhooks</strong> — ausgehende Benachrichtigungen an andere Systeme</li><li><strong>Links</strong> — Übersicht aller externen Links dieses Space</li></ul><h2 id="ubergreifende-elemente" tabindex="-1">Übergreifende Elemente <a class="header-anchor" href="#ubergreifende-elemente" aria-label="Permalink to &quot;Übergreifende Elemente&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Suche</strong></td><td>Durchsucht Einträge</td></tr><tr><td><strong>Hilfe-Menü</strong></td><td>Zugang zu Hilfe und Neuerungen</td></tr><tr><td><strong>Chat</strong></td><td>Direkter Kontakt zum Support</td></tr><tr><td><strong>Vollbild</strong></td><td>Blendet die Seitenleiste aus</td></tr><tr><td><strong>Hinweis auf Änderungen</strong></td><td>Meldet, wenn andere Personen das Grid geändert haben</td></tr></tbody></table><p>Wird eine neue Programmversion bereitgestellt, erscheint ein Hinweis mit der Aufforderung, die Seite neu zu laden.</p>',53)])])}const f=t(d,[["render",o]]);export{m as __pageData,f as default};
